{
  "root_cause": "The datepicker, when shown, does not release focus on the Tab key, causing focus to remain locked in the departure date input.",
  "repair_strategy": "Add a keydown listener for the Tab key on the datepicker input that hides the datepicker when Tab is pressed and the datepicker is shown, allowing the browser to handle focus navigation normally.",
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void",
      "after": "  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void
  protected declare _onTabKey: (event: KeyboardEvent) => void | null"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()",
      "after": "    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()

    // Add keydown listener for Tab to hide datepicker if shown, to allow tabbing out
    if (this._isInput && !this._isInline) {
      this._onTabKey = (event: KeyboardEvent) => {
        if (event.key === 'Tab' && this._isShown) {
          this.hide()
        }
      }
      EventHandler.on(this._element, 'keydown', this._onTabKey)
    }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }",
      "after": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    // Clean up Tab key listener
    if (this._onTabKey) {
      EventHandler.off(this._element, 'keydown', this._onTabKey)
      this._onTabKey = null
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }"
    }
  ],
  "expected_accessibility_effect": "Tab key moves focus from the departure date field to the next field in the form (passengers) when the datepicker is open.",
  "functional_risks": [
    "Hiding the datepicker on Tab may interrupt user interaction if they were navigating within the datepicker using Tab.",
    "This fix only applies to non-inline datepickers attached to input elements; other configurations are unaffected."
  ],
  "verification_requirements": [
    "Verify that Tab key moves focus from the departure date to the passengers field when the datepicker is open.",
    "Verify that Escape key still closes the datepicker and allows tabbing out.",
    "Verify that Tabbing within the datepicker (if it contains focusable elements) does not unexpectedly close the datepicker.",
    "Verify that the datepicker still functions correctly for date selection when not using Tab."
  ]
}
